"""The slicer's word on a part: G-code read back right, and PrusaSlicer itself
on parts that do and don't need support (support grams, filament, time)."""
import os
import types

import pytest

from mech import slicer
from mech.box import block

GCODE = """\
; generated by PrusaSlicer 2.8.1
M83
;TYPE:External perimeter
G1 X10 Y10 E1.5
G1 X20 Y10 E2.5
G1 E-0.8 F2100
G1 E0.8 F2100
;TYPE:Support material
G1 X30 Y10 E3.0
G1 X40 Y10 F9000
G1 X50 Y10 E1.0
;TYPE:Support material interface
G1 X60 Y10 E1.0
;TYPE:Solid infill
G1 X60 Y20 E2.0

; filament used [mm] = 11.00
; filament used [cm3] = 0.03
; filament used [g] = 0.04
; filament cost = 0.00
; total filament used [g] = 0.04
; total filament cost = 0.00
; estimated printing time (normal mode) = 1h 2m 3s

; prusaslicer_config = begin
; filament_density = 1.27
; filament_diameter = 1.75
; use_relative_e_distances = 1
; prusaslicer_config = end
"""


def test_parse_gcode_sums_support_by_type():
    r = slicer.parse_gcode(GCODE)
    area = 3.14159265 * 0.875 ** 2  # mm2 of 1.75 mm filament
    assert r["filament_g"] == 0.04 and r["filament_m"] == 0.01
    assert r["support_cm3"] == round(5.0 * area / 1000, 2)
    assert r["support_g"] == round(5.0 * area / 1000 * 1.27, 2)
    # A retract and its unretract cancel; a travel adds nothing.
    assert r["by_type_g"]["external perimeter"] == round(4.0 * area / 1000 * 1.27, 2)
    assert set(r["by_type_g"]) == {"external perimeter", "support material",
                                   "support material interface", "solid infill"}
    assert r["time"] == "1h 2m 3s" and r["time_s"] == 3723


def test_parse_gcode_wants_relative_e():
    with pytest.raises(ValueError):
        slicer.parse_gcode(GCODE.replace("use_relative_e_distances = 1", "use_relative_e_distances = 0"))


@pytest.mark.parametrize("s,want", [("50m 39s", 3039), ("2h 0m 1s", 7201), ("1d 1h 1m 1s", 90061), ("45s", 45)])
def test_parse_time(s, want):
    assert slicer.parse_time(s) == want


def _slicer():
    if slicer.find():
        return slicer.find()
    if os.environ.get("MECH_NEED_SLICER"):
        return slicer.ensure()
    pytest.skip("no PrusaSlicer here (mech slice --install); CI installs it")


@pytest.fixture(scope="module")
def stls(tmp_path_factory):
    from build123d import export_stl
    d = tmp_path_factory.mktemp("slice")
    flat = block(0, 0, 0, 30, 20, 6)
    # A 40 x 40 table on a 10 x 10 stem: 15 mm of air under most of its top.
    table = block(15, 15, 0, 25, 25, 15) + block(0, 0, 15, 40, 40, 18)
    out = {}
    for name, p in (("flat", flat), ("table", table)):
        export_stl(p, str(d / f"{name}.stl"))
        out[name] = d / f"{name}.stl"
    return out


def test_real_slice_support_only_where_needed(stls):
    s = _slicer()
    got = slicer.slice_parts(stls, slicer=s)
    flat, table = got["flat"], got["table"]
    assert "error" not in flat and "error" not in table, got
    assert flat["support_g"] == 0.0
    assert table["support_g"] > 1.0 and table["support_share"] > 0.1
    # 3.6 cm3 of block at 20 % infill and 4 walls: less than solid, well over nothing.
    solid_g = 30 * 20 * 6 / 1000 * 1.27
    assert 0.3 * solid_g < flat["filament_g"] < 1.1 * solid_g
    assert 60 < flat["time_s"] < 3600
    assert table["time_s"] > flat["time_s"]
    assert abs(sum(table["by_type_g"].values()) - table["filament_g"]) < 0.1


def test_build_passes_slice_options_per_part(stls):
    """An enclosure's SLICE: options for all parts, a dict value for one part."""
    _slicer()
    from mech.cli import slice_printed
    mod = types.SimpleNamespace(SLICE={"fill_density": "10%", "table": {"support_material": 0}})
    got = slice_printed(mod, dict(stls))
    assert got["table"]["support_g"] == 0.0
    assert got["flat"]["filament_g"] > 0
    md = slicer.markdown(got)
    assert "| table |" in md and "| all |" in md


def test_profile_overrides_in_place():
    text = slicer.profile({"perimeters": 3, "support_material": False, "ironing": 1})
    keys = [ln.partition("=")[0].strip() for ln in text.splitlines() if "=" in ln and not ln.startswith("#")]
    assert len(keys) == len(set(keys))
    assert "perimeters = 3" in text and "support_material = 0" in text and "ironing = 1" in text


def test_find_falls_back_to_the_shared_environment(tmp_path, monkeypatch):
    monkeypatch.delenv("MECH_SLICER", raising=False)
    monkeypatch.setenv("MECH_HOME", str(tmp_path / "home"))
    shared = tmp_path / "shared"
    monkeypatch.setenv("MECH_SHARED", str(shared))
    assert slicer.find() is None
    w = shared / f"prusaslicer-{slicer.VERSION}" / "prusa-slicer"
    w.parent.mkdir(parents=True)
    w.write_text("#!/bin/sh\n")
    assert slicer.find() == w
    own = tmp_path / "home" / f"prusaslicer-{slicer.VERSION}" / "prusa-slicer"
    own.parent.mkdir(parents=True)
    own.write_text("#!/bin/sh\n")
    assert slicer.find() == own
